{
  "name": "flowpane",
  "version": "0.10.0",
  "description": "A live workflow pane: replaces the default Workflow progress list with a phase-by-phase graph or a timeline beside the transcript, showing each agent's state, timing, live token spend, tool calls, what it is saying, and prompt.",
  "author": {
    "name": "Mutlu Polatcan",
    "url": "https://github.com/mpolatcan"
  },
  "homepage": "https://github.com/mpolatcan/flowpane",
  "repository": "https://github.com/mpolatcan/flowpane",
  "license": "MIT",
  "keywords": [
    "workflow",
    "visualization",
    "graph",
    "timeline",
    "pane",
    "subagents"
  ],
  "userConfig": {
    "orientation": {
      "type": "string",
      "title": "Layout",
      "description": "Which way the phases run: 'horizontal' (or 'across') runs them across the pane, 'vertical' (or 'down') runs them down it, 'timeline' draws bars against the clock, 'list' draws a row per agent instead of bands of cards, and 'auto' (or 'fits') follows the pane's shape. The settings dialog lists the five by name. The names these carried before 0.5.0 — 'flow', 'stack' and 'time' — still select their layouts.",
      "default": "auto"
    },
    "detailRows": {
      "type": "number",
      "title": "Detail height",
      "description": "Rows the detail dialog takes when a node is selected (5 to 32), capped at what the pane can inset around it. Prompt and Tool Calls sit side by side; the answer takes a row of its own underneath.",
      "default": 24
    },
    "paneRows": {
      "type": "number",
      "title": "Pane height",
      "description": "Rows the pane asks for (6 to 80). 0 lets the surface pick its own height, which is what a dock beside the transcript usually wants.",
      "default": 0
    }
  }
}
